import fs from 'node:fs';
const file = process.argv[2];
const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);
const out = [];
let prevTs = null;
for (const l of lines) {
  let e; try { e = JSON.parse(l); } catch { continue; }
  const ts = e.timestamp || null;
  let gap = '';
  if (ts && prevTs) {
    const d = (new Date(ts) - new Date(prevTs)) / 1000;
    if (d >= 20) gap = ` [+${d.toFixed(0)}s]`;
  }
  if (ts) prevTs = ts;
  const t = e.type;
  if (t === 'queue-operation') { out.push(`QUEUE ${ts}: ${String(e.content).slice(0,400)}`); continue; }
  if (t === 'user') {
    const c = e.message?.content;
    if (typeof c === 'string') { out.push(`USER ${ts}${gap}: ${c.slice(0,1500)}`); }
    else if (Array.isArray(c)) {
      for (const b of c) {
        if (b.type === 'text') out.push(`USER ${ts}${gap}: ${b.text.slice(0,1500)}`);
        else if (b.type === 'tool_result') {
          const txt = typeof b.content === 'string' ? b.content : Array.isArray(b.content) ? b.content.map(x=>x.text||'').join(' ') : '';
          out.push(`  RESULT${gap}${b.is_error?' ERROR':''}: ${String(txt).replace(/\s+/g,' ').slice(0,300)}`);
        }
      }
    }
    continue;
  }
  if (t === 'assistant') {
    const c = e.message?.content || [];
    for (const b of c) {
      if (b.type === 'text' && b.text.trim()) out.push(`ASSISTANT ${ts}${gap}: ${b.text.replace(/\s+/g,' ').slice(0,1800)}`);
      else if (b.type === 'tool_use') {
        const inp = JSON.stringify(b.input).replace(/\s+/g,' ').slice(0,320);
        out.push(`  TOOL ${b.name}${gap}: ${inp}`);
      }
    }
    continue;
  }
  if (t === 'system' && e.content) out.push(`SYS: ${String(e.content).replace(/\s+/g,' ').slice(0,200)}`);
}
console.log(out.join('\n'));
EOF
